GT={'T^p':(lambda q,t: t**q[0],1),'exp(-q/T)':(lambda q,t: np.exp(-q[0]/t),1),'exp(-qT)':(lambda q,t: np.exp(-q[0]*t),1),'1':(lambda q,t: np.ones_like(t),0),'T':(lambda q,t: t,0),'1/T':(lambda q,t: 1/t,0)}
C3={'const':(lambda q,t: np.ones_like(t),0),'exp(-q/T)':(lambda q,t: np.exp(-q[0]/t),1),'T^p':(lambda q,t: t**q[0],1)}
